// ui-chart.js — the drawn Chart (docs/loop/M1.md §3, SPEC §5.4, §5.5 (f), §8.8; M1 step 3b). The world map's bake for the shipped
// sheets (src/chart-art.js, generated by tools/world-map/build.mjs --game) and its live layer (src/chart-draw.js, the same code
// the published map draws with), and each owned water's own sheet drawn from the game's arena data, pinned beside its true place.
// Created by ui-loop.js (the loop's view) only under data.LOOP_ENABLED; until its images are decoded, or if they cannot be, the
// Chart is 1a's list (M1.md §3.2, §3.6) and nothing else changes.
//
//   createChartView(deps) → {prepare, ready, failed, render(entry, body, model, opts), openSealed, debug(cmd, arg)}
//   pure (node: tools/tests/ui-chart.test.mjs): CHART_FONTS · FONT_FACES · waterGeometry · placeSites · chartPlaces · targetOverlaps
//                                              · CHART_FIXTURE
//
// The tap targets are DOM buttons over the canvas, placed from the layout the drawing returns (M1.md §3.4): the water
// ([data-water]), each owned or priced place ([data-place]), the catalogue's book ([data-action=catalogue]), the sealed sheet
// ([data-sealed]); the hold's slots (.gw-slot) and Sail ([data-action=sail]) sit under the sheet, as on 1a's list. The Chart
// writes nothing but the chosen place (meta.loop.chartPick). Never a ring or a disc round the raft or the player.
import { drawChart, seal, rolledSheet, deckle, ease, vignetteLanding, vignetteMossmere, vignetteSporewood, chartReach } from './chart-draw.js';
import { CHART_ART } from './chart-art.js';
import { gildStep, gildCard, brookStep, brookCard } from './chart-gild.js';   // M1 step 5b (lane 5b-home); the brook behind the Veil (LOST-TACKLE §5.2)
import { buildLayout, sheetOf } from './world-layout.js';
import { shoreAt as outlineShoreAt, arcAt as outlineArcAt } from './world-outline.js';   // LAKE2 lane C: an outline water's banks and reed runs
import { WATERCRAFT } from './watercraft.js';
import { drawFishInk } from './ui-fishart.js';

const fin = Number.isFinite;   // (one name for it: the Chart's code line, M1.md §3.2)
const isObj = (o) => !!o && typeof o === 'object' && !Array.isArray(o);
const arr = (v) => (Array.isArray(v) ? v : []);
const num = (v, d = 0) => (typeof v === 'number' && fin(v) ? v : d);
const clamp01 = (v) => (fin(v) ? Math.min(1, Math.max(0, v)) : 0);

/** The chart's faces (M1.md §3.1): it letters in 'IM Fell English' (the court surveyors' hand), never in Alegreya: the names in
 *  its italic, the figures (prices, weights, the catch count) in its roman, with their old-style figures; "Coming soon" in the
 *  margin hand. */
export const CHART_FONTS = Object.freeze({
  chart: "'IM Fell English', 'IM Fell English SC', Georgia, serif",
  figure: "'IM Fell English', Georgia, serif",
  hand: "'Cedarville Cursive', 'Segoe Script', 'Bradley Hand', cursive",
});
/** The faces loaded with the images in idle time, so the Chart's first paint letters in them (M1.md §3.1). */
export const FONT_FACES = Object.freeze(['italic 16px "IM Fell English"', '16px "IM Fell English"', '16px "Cedarville Cursive"']);
const INK_SHEET = 1.2, INK_PLACE = 0.8;   // s: the first sheet's ink-in (WORLD.md §10's reveal), a bought place's (M1.md §3.4)
/** The landmark vignettes of the shipped sheets' marks (n: chart-art.js's live marks), the only ones the game bundles (M1.md §3.2):
 *  each slice adds its waters' (the node test checks every mark the art carries has its vignette here). */
export const SHIPPED_VIGNETTES = Object.freeze({ 0: vignetteLanding, 1: vignetteMossmere, 2: vignetteSporewood });   // (LAKE2 lane C: Sporewood's caps)

/**
 * A water's own sheet as the Chart draws it, from the game's arena data (M1.md §3.1 item 3): its shore (world-layout's shore
 * radius, so the sheet's outline is the world's), its isles, the Toppled Bridge's piers, its deep pools, its gate and its docks
 * (the Jetty first). Pure.
 */
export function waterGeometry(D, waterId) {
  const zone = D?.ZONE_BY_ID?.[waterId] || arr(D?.ZONES).find((z) => z?.id === waterId) || null;
  if (!zone) return null;
  const A = zone.arena || {};
  let Ly = null;
  try { Ly = buildLayout(zone); } catch { /* the sheet drawn from the arena's radius */ }
  const shoreR = Ly?.shoreR || null, N = Ly?.notch ? { ...Ly.notch, ray: null } : null;
  const R = num(A.radius, 60);
  const shore = [];
  let Rmax = 0;
  // LAKE2 §3.1 (lane W1): an outline water's sheet is the world's own outline (world-layout.sheetOf: its shore every 2 m, each island's
  // own, `shoreDist` (x, z) → m, + in the water, the side of the shore for the pen)
  const S = Ly && sheetOf(Ly);
  if (S) { shore.push(...S.shore); Rmax = S.Rmax; } else for (let i = 0; i < 120; i++) {
    const a = (i / 120) * Math.PI * 2, r = shoreR ? shoreR(a) : R;
    Rmax = Math.max(Rmax, r);
    shore.push([Math.round(Math.cos(a) * r * 100) / 100, Math.round(Math.sin(a) * r * 100) / 100]);
  }
  const pts = (list) => arr(list).filter((p) => isObj(p) && fin(p.x) && fin(p.z));
  const docks = pts(A.docks).map((d) => ({ x: d.x, z: d.z }));
  // LAKE2 §6.2 (lane C): an outline water's sheet also carries each shore sample's bank (its height, its normal into the land: the
  // hachures fall that way where it stands high), its reed runs as arc lengths, its in and out (WATERCRAFT's), and its mooring
  let more = null;
  const O = S && Ly?.outline;
  if (O) {
    const n = S.shore.length, q = {}, banks = [];
    for (let i = 0; i < n; i++) { outlineShoreAt(O, (i / n) * O.len, q); banks.push({ nx: Math.round(q.nx * 1000) / 1000, nz: Math.round(q.nz * 1000) / 1000, h: Math.round(q.h * 100) / 100 }); }
    const G = WATERCRAFT?.[waterId]?.geometry || {}, M = D?.LOOP?.mooring?.[waterId];
    const pt = (p) => (isObj(p) && fin(p.x) && fin(p.z) ? { x: p.x, z: p.z } : null);
    more = { banks, len: O.len, reeds: arr(G.reedRuns).filter((r) => Array.isArray(r) && r.length === 2).map(([u0, u1]) => [outlineArcAt(O, u0), outlineArcAt(O, u1)]),
      inflow: pt(G.inflow), outflow: pt(G.outflow), mooring: isObj(M) && isObj(M.hull) ? { hull: { ...M.hull }, murk: isObj(M.murk) ? { ...M.murk } : null } : null };
  }
  return {
    id: waterId, name: zone.name, R, Rmax, shore, shoreAt: shoreR || null, notch: N, ...(S && S.extra), ...(more || {}),
    islands: pts(A.islands).map((q) => ({ x: q.x, z: q.z, r: num(q.r, 4), kind: q.kind || 'rock', ...(S && S.isle(q)) })),
    piers: pts(A.pillars).filter((p) => p.kind === 'pier').map((p) => ({ x: p.x, z: p.z, r: num(p.r, 1.4) })),
    deep: pts(A.deepPools).map((p) => ({ x: p.x, z: p.z, r: num(p.r, 10) })),
    gate: A.gate && fin(A.gate.x) ? { x: A.gate.x, z: A.gate.z } : null,
    docks, jetty: docks[0] || null,
  };
}

/** Where each place of a water sits (its arena site, so the Chart matches the mist in the world): LOOP.places, then the water's
 *  v3 places (MOSSMERE_V3), then the built places. {placeId: {x, z}}. Pure. */
export function placeSites(D, waterId) {
  const out = {};
  const put = (p) => { if (isObj(p) && typeof p.id === 'string' && fin(p.x) && fin(p.z) && !out[p.id]) out[p.id] = { x: p.x, z: p.z }; };
  const LP = D?.LOOP?.places;
  // (LAKE 2, lane C: a later water's place keeps its geometry beside it, read through loopPlace: SPOREWOOD_LOOP.places)
  for (const p of Array.isArray(LP) ? LP : isObj(LP) ? Object.entries(LP).map(([id, v]) => ({ id, ...v })) : []) {
    if (!p.zone || p.zone === waterId || p.water === waterId) put(p);
    if (!fin(p.x) && typeof D?.loopPlace === 'function') { const q = D.loopPlace(p.id); if (isObj(q) && (q.zone === waterId || q.water === waterId) && waterId !== 'mossmere') put({ ...q, id: p.id }); }
  }
  if (waterId === 'mossmere') arr(D?.MOSSMERE_V3?.places).forEach(put);
  arr(D?.PLACES).filter((p) => p?.zone === waterId).forEach(put);
  return out;
}

/**
 * The places of the debug fixture (M1.md §2.4, the Mossmere's four; M1 step 3b proves the drawing with them before step 3a ships
 * LOOP.places): `state` 'later' (two owned, one with its giant landed, two priced), 'three' (one owned; the two cheapest priced,
 * the Bell Pool's blot unpriced), 'none' (all mist, none priced: the tutorial's view). Prices are LOOP.waters' by kind.
 */
export function CHART_FIXTURE(D, state = 'later') {
  const P = D?.LOOP?.waters?.mossmere?.prices || { day: 60, old: 150, night: 260, crown: 500 };
  const base = [
    { id: 'lily_maze', name: 'The Lily Maze', kind: 'day' }, { id: 'under_the_span', name: 'Under the Span', kind: 'old' },
    { id: 'buoy_lights', name: 'The Buoy Lights', kind: 'night' }, { id: 'bell_pool', name: 'The Bell Pool', kind: 'crown' },
  ];
  const own = state === 'later' ? ['lily_maze', 'under_the_span'] : state === 'three' ? ['lily_maze'] : state === 'all' ? base.map((b) => b.id) : [];
  const unowned = base.filter((b) => !own.includes(b.id)).sort((a, b) => P[a.kind] - P[b.kind]);
  const priced = state === 'none' ? [] : unowned.slice(0, 2).map((b) => b.id);   // Murk's three: the two cheapest place maps (the third is the next lake)
  const best = { lily_maze: { speciesId: 'candlefin_koi', weight: 0.94 }, under_the_span: { speciesId: 'reedjaw_pike', weight: 4.1 }, buoy_lights: { speciesId: 'lampsipper', weight: 0.3 }, bell_pool: { speciesId: 'weeping_carp', weight: 2.6 } };
  return base.map((b) => ({ ...b, owned: own.includes(b.id), price: priced.includes(b.id) ? P[b.kind] : null, best: own.includes(b.id) ? best[b.id] : null,
    giantLanded: state !== 'none' && b.id === 'under_the_span' && own.includes(b.id), marked: state === 'all' && b.id === 'buoy_lights', wounds: state === 'all' && b.id === 'bell_pool' ? 2 : 0 }));
}

/** chartModel's places with the names the drawing letters (the place's own name; a mist blot is never named). Pure. */
export function chartPlaces(D, places) {
  const nameOf = (id) => {
    const LP = D?.LOOP?.places;
    const lp = Array.isArray(LP) ? LP.find((p) => p?.id === id) : isObj(LP) ? LP[id] : null;
    // (LAKE 2, lane C: a later water's place names itself through loopPlace, beside its geometry: SPOREWOOD_LOOP.places)
    return lp?.name || arr(D?.MOSSMERE_V3?.places).find((p) => p?.id === id)?.name || D?.PLACE_BY_ID?.[id]?.name || (typeof D?.loopPlace === 'function' ? D.loopPlace(id)?.name : null) || null;
  };
  return arr(places).filter(isObj).map((p) => ({ ...p, name: p.owned === true ? p.name || nameOf(p.id) || p.id : null }));
}

/** The pairs of tap targets that overlap (the water is the sheet's backdrop: a place on it is not an overlap). Pure. */
export function targetOverlaps(targets) {
  const out = [], T = arr(targets).filter((t) => !t.backdrop);
  for (let i = 0; i < T.length; i++) for (let j = i + 1; j < T.length; j++) {
    const a = T[i].rect, b = T[j].rect;
    if (a[0] < b[0] + b[2] && a[0] + a[2] > b[0] && a[1] < b[1] + b[3] && a[1] + a[3] > b[1]) out.push([T[i].id, T[j].id]);
  }
  return out;
}

// ================================================================== the view
export function createChartView(deps) {
  const { K, ctx, D, h, report = () => {} } = deps;
  const S = {
    status: 'idle', art: null, error: null, fonts: false, seenOwned: null, seenGiants: null, firstPaint: null, fixture: null,
    pick: null, ink: null, raf: 0, draws: 0, lastLayout: null, sealedFrom: null,
  };
  const now = () => (typeof performance !== 'undefined' ? performance.now() : Date.now());

  // ---- the images, decoded once in idle time after the title is up, and the chart's faces with them (M1.md §3.2)
  // a data: URI decodes through an <img> only, never fetch(): a page host's Content-Security-Policy may block fetch() of data:
  // (connect-src) while images stay allowed (img-src) — the user's phone in the app showed the Landing's sheet blank (16 Nov). An
  // <img> that fails throws: the status goes to 'failed' and the list Chart covers it
  const decode = async (uri) => {
    const img = new Image(); img.decoding = 'async'; img.src = uri; await img.decode();
    if (typeof createImageBitmap === 'function') { try { return await createImageBitmap(img); } catch { /* the <img> itself draws */ } }
    return img;
  };
  // the paper (M1's view of the bake's paper, a 167 x 125 px JPEG stretched about 11 times over the vellum): its signal is a slow
  // mottle of a level or two, under the JPEG's 8 x 8 blocks, so it is blurred once at its own size (a box of 3 px, twice each way)
  // before it is ever stretched: the mottle stays, the blocks never show as patches on the bare paper
  function softPaper(img) {
    try {
      const w = img.width, hh = img.height, c = document.createElement('canvas'); c.width = w; c.height = hh;
      const g = c.getContext('2d'); g.drawImage(img, 0, 0);
      const d = g.getImageData(0, 0, w, hh), A = Float32Array.from(d.data), B = new Float32Array(A.length);
      const pass = (s, t, hz) => {
        for (let y = 0; y < hh; y++) for (let x = 0; x < w; x++) for (let ch = 0; ch < 3; ch++) {
          let v = 0;
          for (let q = -3; q <= 3; q++) v += s[((hz ? y : Math.min(hh - 1, Math.max(0, y + q))) * w + (hz ? Math.min(w - 1, Math.max(0, x + q)) : x)) * 4 + ch];
          t[(y * w + x) * 4 + ch] = v / 7;
        }
      };
      for (let i = 0; i < 2; i++) { pass(A, B, true); pass(B, A, false); }
      for (let i = 0; i < A.length; i++) if (i % 4 < 3) d.data[i] = A[i];
      g.putImageData(d, 0, 0);
      return c;
    } catch { return img; }
  }
  async function prepare() {
    if (S.status !== 'idle') return S.status;
    S.status = 'loading';
    try {
      const A = CHART_ART;
      if (!A || !arr(A.sheets).length) throw new Error('no chart art');
      const fonts = typeof document !== 'undefined' && document.fonts?.load
        ? Promise.race([Promise.all(FONT_FACES.map((f) => document.fonts.load(f))), new Promise((r) => setTimeout(r, 6000))]).catch(() => {})
        : Promise.resolve();
      // (LAKE 2, lane C: the first sheet and every sheet whose water's map the save owns now; another only once its map is bought and
      // the Chart draws it (sheetsFor): a sheet baked ahead of its gate is never decoded, and costs a phone nothing until then)
      const lakes = arr(ctx.state?.meta?.loop?.maps?.lakes);
      const [sheets, paper] = await Promise.all([Promise.all(A.sheets.map(async (s, i) => ({ ...s, image: i === 0 || lakes.includes(s.water) ? await decode(s.uri) : null }))), A.paper ? decode(A.paper.uri) : null, fonts]);
      S.fonts = typeof document !== 'undefined' && document.fonts?.check ? FONT_FACES.every((f) => document.fonts.check(f)) : true;
      S.art = { sheets, paper: paper ? { ...A.paper, image: softPaper(paper) } : null, live: A.live };
      S.status = 'ready';
    } catch (e) {
      S.status = 'failed'; S.error = String(e?.message || e);
      report('chart.decode', e);
      try { console.warn('[chart] the drawn Chart could not decode its art; the Chart is the list', e); } catch { /* ignore */ }
    }
    return S.status;
  }

  /** LAKE 2, lane C: the sheets the model draws (chartReach's n) decoded, each once; the Chart repaints as each comes in. */
  function sheetsFor(m) {
    if (S.status !== 'ready' || !S.art) return;
    const n = chartReach(m, S.art).n;
    for (const q of S.art.sheets) {
      if (q.n > n || q.image || q.loading) continue;
      q.loading = true;
      decode(q.uri).then((img) => { q.image = img; q.loading = false; S.repaint?.(); }).catch((e) => { q.loading = false; report('chart.decode', e); });
    }
  }
  // ---- the model as the drawing reads it
  const meta = () => ctx.state?.meta || null;
  /** A chosen place the Chart can still choose: its water drawn and, for a place, that place owned there. */
  const pickable = (m, p) => isObj(p) && m.sheets.some((s) => s.waterId === p.water && (!p.place || arr(s.places).some((q) => q.id === p.place && q.owned === true)));
  function drawModel(model) {
    // the view's memory of the save (the chosen place, the places and giants seen) belongs to one save: Erase or a load starts it again
    if (S.meta !== meta()) { S.meta = meta(); S.pick = null; S.seenOwned = null; S.seenGiants = null; }
    const m = { ...model, sheets: arr(model?.sheets).map((s) => ({ ...s })) };
    if (S.fixture && m.sheets[0]) m.sheets[0].places = S.fixture.places;   // (debug builds only: the M1 §2.4 fixture, ctx.debug.loop.chart)
    for (const s of m.sheets) s.places = chartPlaces(D(), s.places);
    if (S.fixture?.next !== undefined && !m.tutorial) m.next = S.fixture.next;
    const open = pickable(m, model?.pick) ? { ...model.pick } : { water: m.sheets[0]?.waterId ?? null, place: null };
    // the chosen place, checked on every render against what the Chart draws now; else the model's own (open water)
    if (S.pick && !pickable(m, S.pick)) S.pick = open;
    m.pick = S.pick || open;
    return m;
  }
  const fishCache = new Map();
  function fishGlyph(id) {
    if (fishCache.has(id)) return fishCache.get(id);
    let c = null;
    try {
      const sp = D()?.SPECIES_BY_ID?.[id] || arr(D()?.SPECIES).find((x) => x?.id === id);
      if (sp && typeof document !== 'undefined') {
        c = document.createElement('canvas'); drawFishInk(c, sp, { w: 88, h: 48 });
        // the glyph in the Chart's own ink (the built drawing is pale, for the night): its shape kept, its colour the sepia-violet ink
        const g = c.getContext('2d'); g.globalCompositeOperation = 'source-in'; g.fillStyle = 'rgba(59,46,68,.92)'; g.fillRect(0, 0, c.width, c.height);
      }
    } catch { c = null; }
    fishCache.set(id, c);
    return c;
  }
  // the Chart's still part, drawn once and kept (chart-draw.js drawChart: the vellum, the first sheet, each water's sheet and lake):
  // one frame's worth only (at DPR 3 a phone's is about 8 MB), drawn again on a resize
  const baseCache = {
    map: new Map(),
    get(k) { return this.map.get(k) || null; },
    set(k, c) { this.map.clear(); this.map.set(k, c); },
    canvas(w, h) { const c = document.createElement('canvas'); c.width = w; c.height = h; return c; },
  };
  const geoCache = new Map();
  const geometry = (id) => { if (!geoCache.has(id)) geoCache.set(id, waterGeometry(D(), id)); return geoCache.get(id); };

  // ---- one render: the panel, the sheet (canvas + its hit layer), the hold's slots, Sail
  function render(entry, body, model, opts) {
    const { panel, btn, line, slotsInk, slotStep, sail, onPick, onBuy, onCatalogue, onSealed } = opts;
    const st = entry.state;
    S.renders = (S.renders || 0) + 1;
    const m = drawModel(model);
    sheetsFor(m);
    const { panel: pn, content, foot } = panel(entry, body, { cls: `gw-p-chart gw-p-chart--drawn${line ? ' gw-p-chart--line' : ''}${opts.reduced ? ' gw-rm' : ''}` });
    pn.dataset.loop = 'chart';
    content.innerHTML = `${line ? '<p class="gw-murk-line gw-in"></p>' : ''}<div class="gw-chart gw-chart--drawn"><div class="gw-chart-sheet"><canvas class="gw-chart-cv" aria-hidden="true"></canvas><div class="gw-chart-hits"></div></div></div>`;
    if (line) content.querySelector('.gw-murk-line').textContent = line;
    const wrap = content.querySelector('.gw-chart'), sheetEl = content.querySelector('.gw-chart-sheet'), cv = sheetEl.querySelector('canvas'), hits = sheetEl.querySelector('.gw-chart-hits');
    // the hold's empty slots under the sheet (they ink in 0.25 s apart in the tutorial's beat, as on 1a's list)
    const slots = h('div', 'gw-hold gw-chart-hold');
    for (let i = 0; i < Math.max(0, m.hold?.slots | 0); i++) {
      const cell = h('span', `gw-slot${slotsInk ? ' gw-ink' : ''}`);
      cell.dataset.filled = '0';
      if (slotsInk) cell.style.animationDelay = `${(0.35 + i * slotStep).toFixed(2)}s`;
      slots.appendChild(cell);
    }
    foot.appendChild(slots);
    foot.appendChild(sail);

    // ---- what inks in on this open: the first sheet the first time the Chart ever opens; a place bought since the last open
    const ml = meta()?.loop;
    if (!st.inkPlanned) {
      st.inkPlanned = true;
      if (S.timing) { S.timing.opened = now(); S.timing.paints = []; S.timing.openToPaint = null; }
      const first = m.tutorial === true && !isObj(ml?.chartPick);
      const owned = new Set(), giants = new Set();
      for (const s of m.sheets) for (const p of s.places) { if (p.owned) owned.add(p.id); if (p.giantLanded) giants.add(p.id); }
      const places = {};
      if (S.seenOwned) for (const id of owned) if (!S.seenOwned.has(id)) places[id] = 0;
      const stamps = S.seenGiants ? [...giants].filter((id) => !S.seenGiants.has(id)) : [];
      S.seenOwned = owned; S.seenGiants = giants;
      st.ink = opts.reduced ? null : { t0: null, sheet: first ? 0 : 1, places };
      if (stamps.length) { try { K.sfx?.('seal_stamp', { volume: 0.5 }); } catch { /* ignore */ } }   // a giant landed: its ★ with one small stamp
      if (!S.pick) {   // the first open of a session (or of a save) chooses the place sailed to last, if the Chart can still choose it
        const cp = ml?.chartPick;
        S.pick = !m.tutorial && pickable(m, cp) ? { water: cp.water, place: cp.place || null } : { ...m.pick };
      }
      m.pick = S.pick;
      if (ml && !isObj(ml.chartPick)) ml.chartPick = { ...S.pick };
    }

    const paint = (t) => {
      const t0 = now();
      const r = sheetEl.getBoundingClientRect();
      const w = Math.round(r.width), hh = Math.round(r.height);
      if (w < 40 || hh < 40) return null;
      const dpr = Math.min(3, (typeof devicePixelRatio === 'number' && devicePixelRatio) || 1);
      if (cv.width !== Math.round(w * dpr) || cv.height !== Math.round(hh * dpr)) { cv.width = Math.round(w * dpr); cv.height = Math.round(hh * dpr); cv.style.width = `${w}px`; cv.style.height = `${hh}px`; }
      const ink = st.ink;
      let sheetK = 1, placeK = {}, more = false;
      if (ink) {
        if (ink.t0 == null) ink.t0 = t;
        const el = (t - ink.t0) / 1000;
        sheetK = ink.sheet >= 1 ? 1 : Math.min(1, el / INK_SHEET); if (sheetK < 1) more = true;
        for (const id of Object.keys(ink.places)) { placeK[id] = Math.min(1, Math.max(0, (el - (ink.sheet < 1 ? INK_SHEET : 0)) / INK_PLACE)); if (placeK[id] < 1) more = true; }
        if (S.inkHold != null) { // (debug builds: the ink-in held at one point of its way, for the look's capture)
          sheetK = ink.sheet >= 1 ? 1 : S.inkHold; for (const id of Object.keys(ink.places)) placeK[id] = S.inkHold; more = false;
        }
      }
      const G5 = gildStep(ml, m, now(), st, opts.reduced); more ||= G5.more;   // M1 step 5b: the gilding's re-inking (on the page's own clock)
      const B5 = S.inkHold != null ? { k: S.inkHold, more: false } : brookStep(ml, m, now(), st, opts.reduced); more ||= B5.more;   // LOST-TACKLE §5.2: the brook's ink-in, once
      const g = cv.getContext('2d');
      const view = {
        gild: (c, d, mm, a, v) => { brookCard(c, d, mm, a * B5.k, v); return gildCard(c, d, mm, a * G5.k, v); },
        w, h: hh, dpr, phone: w < 560, F: CHART_FONTS, reduced: !!opts.reduced,
        water: Object.fromEntries(m.sheets.map((s) => [s.waterId, geometry(s.waterId)])), barge: ml?.barge?.water || null,
        sites: Object.assign({}, ...m.sheets.map((s) => placeSites(D(), s.waterId))),
        ink: { sheet: sheetK, places: placeK }, fmtWeight: (w) => (typeof D()?.fmtWeight === 'function' ? D().fmtWeight(w) : ''),   // (pounds: data.fmtWeight, never a bare figure)
        fishGlyph, vignettes: SHIPPED_VIGNETTES, cache: baseCache, words: { soon: D()?.TEXT_LOOP?.comingSoon || 'Coming soon', book: D()?.TEXT_LOOP?.jetty?.journal || 'Journal' }, paperImage: S.art?.paper?.image || null,
        measure: (text, font) => { g.save(); g.font = font; const x = g.measureText(text).width; g.restore(); return x; },
      };
      let L;
      try { L = drawChart(g, m, S.art, view, t); } catch (e) { S.paintErr = String(e?.stack || e); report('chart.paint', e); return null; }
      // (debug builds, ctx.debug.loop.chart('time'): the paint's own call, and the open's render to its first paint; the raster alone
      // is timed by tools/chart-time.mjs, away from the 3D frames a shared software-GL box queues in front of every canvas readback)
      if (S.timing) {
        const r1 = (v) => Math.round(v * 10) / 10;
        S.timing.paints.push({ ms: r1(now() - t0), w, h: hh, dpr });
        if (S.timing.paints.length === 1) S.timing.openToPaint = r1(now() - S.timing.opened);
      }
      S.lastLayout = L; S.lastCanvas = cv; S.draws++;
      if (!S.firstPaint) S.firstPaint = { at: now(), fonts: typeof document !== 'undefined' && document.fonts?.check ? FONT_FACES.every((f) => document.fonts.check(f)) : true, sheetInk: sheetK };
      placeHits(L);
      if (more) { if (!S.raf) S.raf = requestAnimationFrame((tt) => { S.raf = 0; if (cv.isConnected) paint(tt); }); }
      else if (ink && S.inkHold == null) {   // the ink-in done: chart:inked {sheet | place} (M1.md §3.8)
        st.ink = null;
        try { if (ink.sheet < 1) ctx.bus?.emit?.('chart:inked', { sheet: 1 }); for (const id of Object.keys(ink.places)) ctx.bus?.emit?.('chart:inked', { place: id }); } catch { /* ignore */ }
      }
      return L;
    };
    // the hit layer: one DOM button for each tap target, in the drawing's order (the focus order), carrying the tests' selectors
    let hitSig = '';
    const pressed = (t) => (t.kind === 'water' ? m.pick.water === t.water && !m.pick.place : m.pick.place === t.place);
    function placeHits(L) {
      // (a pick alone changes no target: the buttons stay, so the one just pressed keeps its focus; only aria-pressed moves)
      const sig = JSON.stringify(L.targets.map((t) => [t.id, t.rect.map((v) => Math.round(v))]));
      if (sig === hitSig) {
        for (const b of hits.children) { const t = L.targets.find((q) => q.id === b.dataset.id); if (t && (t.kind === 'water' || t.kind === 'place')) b.setAttribute('aria-pressed', String(pressed(t))); }
        return;
      }
      hitSig = sig;
      const focused = hits.contains(document.activeElement) ? document.activeElement.dataset.id : null;
      hits.textContent = '';
      for (const t of L.targets) {
        const b = h('button', `gw-chart-hit gw-chart-hit--${t.kind}`);
        b.type = 'button';
        b.dataset.id = t.id;
        b.style.left = `${t.rect[0]}px`; b.style.top = `${t.rect[1]}px`; b.style.width = `${t.rect[2]}px`; b.style.height = `${t.rect[3]}px`;
        b.setAttribute('aria-label', t.label || t.id);
        if (t.kind === 'water') { b.dataset.water = t.water; b.setAttribute('aria-pressed', String(pressed(t))); }
        if (t.kind === 'place' || t.kind === 'buy') { b.dataset.place = t.place; if (t.kind === 'buy') b.dataset.buy = '1'; else b.setAttribute('aria-pressed', String(pressed(t))); }
        if (t.kind === 'book') { b.dataset.action = 'catalogue'; b.dataset.water = t.water; b.removeAttribute('data-water'); b.dataset.book = t.water; }
        if (t.kind === 'sealed') b.dataset.sealed = t.water;
        if (t.kind === 'sheet') b.dataset.sheet = t.water;   // (LAKE2 lane C: another owned water's mark on the window: its sheet laid beside it)
        b.addEventListener('click', (e) => {
          e.stopPropagation();
          K.sfx?.('ui_click');
          if (t.kind === 'water' || t.kind === 'place' || t.kind === 'sheet') {
            S.pick = { water: t.water, place: t.kind === 'place' ? t.place : null };
            m.pick = S.pick;
            const l = meta()?.loop; if (l) l.chartPick = { ...S.pick };
            try { ctx.bus?.emit?.('chart:pick', { water: S.pick.water, place: S.pick.place }); } catch { /* ignore */ }
            onPick?.(S.pick);
            paint(now());
          } else if (t.kind === 'buy') onBuy?.(t.place);
          else if (t.kind === 'book') onCatalogue?.(t.water);
          else if (t.kind === 'sealed') onSealed?.(t.water, m.next);
        });
        hits.appendChild(b);
        if (focused && focused === t.id) { try { b.focus({ preventScroll: true }); } catch { /* ignore */ } }
      }
    }
    // the first paint once the panel is in the page (the images and the faces are already in: no decode, no fallback face)
    let tries = 0;
    const go = () => { if (cv.isConnected) { try { paint(now()); } catch (e) { S.paintErr = String(e?.stack || e); report('chart.paint', e); } } else if (++tries < 120) requestAnimationFrame(go); };
    requestAnimationFrame(go);
    if (typeof ResizeObserver === 'function') { st.ro?.disconnect?.(); const ro = new ResizeObserver(() => { if (!cv.isConnected) { ro.disconnect(); return; } paint(now()); }); ro.observe(sheetEl); st.ro = ro; }
    st.model = m;
    S.repaint = () => { if (cv.isConnected) paint(now()); };
    return { model: m };
  }

  /** The sealed sheet's card (M1.md §3.4): its wax, the three seals enlarged (the gear seal opens the shelf at its card, the catch seal
   *  the Journal at the current water's list), and "Coming soon" where the price button would be. No fish, no line, no button. */
  function openSealed(next, { panel, onGear, onCatch }) {
    if (!next) return;
    // (LAKE 2, lane C: a shipped water's map not yet bought: Murk's shelf opens at its lake card, SPEC §5.4)
    if (next.shipped === true && !next.seals?.map?.held && typeof K.loop?.openShelf === 'function') { K.loop.openShelf({ tab: 'maps', focus: `lake:${next.waterId}` }); return; }
    K.openModal('chartsealed', (entry, body) => {
      const { panel: pn, content, foot } = panel(entry, body, { cls: 'gw-p-chartsealed' });
      pn.dataset.loop = 'sealed';
      pn.dataset.sealed = next.waterId;
      content.innerHTML = '<div class="gw-chart-sealed-art"><canvas aria-hidden="true"></canvas><div class="gw-chart-sealed-seals"></div></div><p class="gw-chart-sealed-soon"></p>';
      content.querySelector('.gw-chart-sealed-soon').textContent = next.shipped === true ? '' : D()?.TEXT_LOOP?.comingSoon || 'Coming soon';
      foot.remove();
      const cv = content.querySelector('canvas'), row = content.querySelector('.gw-chart-sealed-seals');
      const seals = next.seals || {};
      const keys = ['map', 'gear', 'catch'];
      for (const key of keys) {
        const sl = seals[key] || {};
        const b = h('button', `gw-chart-sealed-seal gw-chart-sealed-seal--${key}${sl.held ? ' gw-held' : ''}`);
        b.type = 'button';
        b.dataset.seal = key;
        b.setAttribute('aria-label', key === 'catch' && fin(sl.need) ? `${sl.have | 0}/${sl.need | 0}` : key);
        if (key === 'map') { b.disabled = true; b.setAttribute('aria-disabled', 'true'); }
        else b.addEventListener('click', (e) => { e.stopPropagation(); K.sfx?.('ui_click'); K.closeModal('chartsealed'); (key === 'gear' ? onGear : onCatch)?.(next); });
        row.appendChild(b);
      }
      const draw = () => {
        const r = cv.getBoundingClientRect(); if (r.width < 20) { requestAnimationFrame(draw); return; }
        const dpr = Math.min(3, devicePixelRatio || 1), w = Math.round(r.width), hh = Math.round(r.height);
        cv.width = w * dpr; cv.height = hh * dpr;
        const g = cv.getContext('2d'); g.setTransform(dpr, 0, 0, dpr, 0, 0); g.clearRect(0, 0, w, hh);
        // a leaf of the Chart's vellum under the sealed sheet and its seals
        g.save(); g.shadowColor = 'rgba(4,2,12,.55)'; g.shadowBlur = 14; g.shadowOffsetY = 3; deckle(g, 4, 4, w - 8, hh - 8, 11, 1.6); g.fillStyle = 'rgb(232,226,230)'; g.fill(); g.restore();
        if (S.art?.paper?.image) { g.save(); deckle(g, 4, 4, w - 8, hh - 8, 11, 1.6); g.clip(); g.globalAlpha = 0.7; g.drawImage(S.art.paper.image, 0, 0, w, hh); g.restore(); }
        rolledSheet(g, w / 2, hh * 0.3, Math.min(w * 0.62, 220), Math.min(hh * 0.3, 70));
        const bs = [...row.children], rr = Math.min(28, w / 10);
        bs.forEach((b, i) => {
          const br = b.getBoundingClientRect(), x = br.left - r.left + br.width / 2, y = br.top - r.top + br.height / 2 - 6;
          const sl = seals[keys[i]] || {};
          const count = keys[i] === 'catch' && fin(sl.need) ? `${sl.have | 0}/${sl.need | 0}` : null;
          seal(g, keys[i], x, y, rr, { held: sl.held === true, tier: sl.tier || 1, count, font: `400 ${Math.max(17, Math.round(rr * 0.66))}px ${CHART_FONTS.figure}` });
        });
      };
      requestAnimationFrame(draw);
    }, { cls: 'gw-m-center gw-m-chartsealed', onEscape: () => K.closeModal('chartsealed') });
  }

  /** The bare-paper test (M1 step 3b's gate: the sheet-2 region of every Chart frame is bare paper): the open Chart's canvas against
   *  the same frame drawn with the paper alone, sampled at each cell of `veil` (tools/tests/fixtures/chart-veil.json: where a later
   *  sheet's ground lies inside the first sheet's box), eroded by `margin` cells from the first sheet's own feathered edge. */
  function veilCheck({ veil, margin = 3, tol = 6 } = {}) {
    const cv = S.lastCanvas, L = S.lastLayout, st = K.entry?.('chart')?.state;
    if (!cv || !L || !veil) return null;
    const v = arr(veil).find((q) => q.sheet === (L.reach || 1)) || arr(veil)[0];   // (LAKE2 lane C: the grid for the sheets owned now)
    const grid = v.rows.map((r) => r.split(',').map((t) => t[0].repeat(Number(t.slice(1)))).join(''));
    const on = (i, j) => j >= 0 && j < grid.length && i >= 0 && i < grid[j].length && grid[j][i] === '1';
    const off = document.createElement('canvas'); off.width = cv.width; off.height = cv.height;
    const g2 = off.getContext('2d'), dpr = cv.width / L.w;
    const view = { w: L.w, h: L.h, dpr, phone: L.phone, F: CHART_FONTS, layers: { first: false }, water: Object.fromEntries(arr(st?.model?.sheets).map((s) => [s.waterId, geometry(s.waterId)])),
      sites: Object.assign({}, ...arr(st?.model?.sheets).map((s) => placeSites(D(), s.waterId))), paperImage: S.art?.paper?.image || null, words: {}, fishGlyph, fmtWeight: () => '' };
    drawChart(g2, st?.model || {}, S.art, view, 0);
    const A = cv.getContext('2d').getImageData(0, 0, cv.width, cv.height).data, B = g2.getImageData(0, 0, cv.width, cv.height).data;
    const c = L.cont;
    let cells = 0, sampled = 0, differing = 0, worst = 0;
    const samples = [];
    for (let j = 0; j < grid.length; j++) for (let i = 0; i < grid[j].length; i++) {
      if (!on(i, j)) continue;
      let core = true;
      for (let dj = -margin; dj <= margin && core; dj++) for (let di = -margin; di <= margin; di++) if (!on(i + di, j + dj)) { core = false; break; }
      if (!core) continue;
      cells++;
      const x = Math.round((c.x + (i + 0.5) * c.k) * dpr), y = Math.round((c.y + (j + 0.5) * c.k) * dpr);
      if (x < 0 || y < 0 || x >= cv.width || y >= cv.height) continue;
      const o = (y * cv.width + x) * 4, d = Math.max(Math.abs(A[o] - B[o]), Math.abs(A[o + 1] - B[o + 1]), Math.abs(A[o + 2] - B[o + 2]));
      sampled++; worst = Math.max(worst, d); if (d > tol) { differing++; if (samples.length < 6) samples.push({ i, j, x, y, a: [A[o], A[o + 1], A[o + 2], A[o + 3]], b: [B[o], B[o + 1], B[o + 2], B[o + 3]] }); }
    }
    return { cells, sampled, differing, worst, samples, cont: { x: c.x, y: c.y, k: c.k, w: c.w, h: c.h }, dpr };
  }

  /** ctx.debug.loop.chart(cmd, arg) (debug builds only): 'fixture' (a CHART_FIXTURE state or an array of places, with or without
   *  `next`), 'clear', 'reset', 'state', 'layout', 'veil', 'ink' (hold every ink-in at `arg` 0..1, or null to let it run), 'time'
   *  (time each paint from the next open: its raster, read back; and the open's render to its first paint). */
  function debug(cmd, arg) {
    if (cmd === 'ink') { S.inkHold = arg == null ? null : clamp01(Number(arg)); if (S.inkHold == null) S.repaint?.(); return S.inkHold; }
    if (cmd === 'time') { S.timing = arg === false ? null : S.timing || { opened: null, openToPaint: null, paints: [] }; return S.timing ? { ...S.timing, paints: S.timing.paints.slice() } : null; }
    if (cmd === 'fixture') {
      const places = Array.isArray(arg) ? arg : Array.isArray(arg?.places) ? arg.places : CHART_FIXTURE(D(), typeof arg === 'string' ? arg : arg?.state || 'later');
      S.fixture = { places, ...(isObj(arg) && 'next' in arg ? { next: arg.next } : {}) };
      return S.fixture;
    }
    if (cmd === 'clear') { S.fixture = null; S.pick = null; return true; }
    if (cmd === 'reset') { S.seenOwned = null; S.seenGiants = null; S.pick = null; return true; }
    if (cmd === 'layout') return S.lastLayout ? { ...S.lastLayout, cont: { ...S.lastLayout.cont } } : null;
    if (cmd === 'veil') return veilCheck(arg);
    return { status: S.status, error: S.error, fonts: S.fonts, firstPaint: S.firstPaint, draws: S.draws, renders: S.renders || 0, paintErr: S.paintErr || null, fixture: !!S.fixture, pick: S.pick, inkHold: S.inkHold ?? null,
      art: S.art ? { sheets: S.art.sheets.map((s) => ({ n: s.n, box: s.box, w: s.image?.width, h: s.image?.height })), paper: !!S.art.paper } : null };
  }
  return { prepare, pick: () => (S.pick ? { ...S.pick } : null), ready: () => S.status === 'ready', failed: () => S.status === 'failed', status: () => S.status, render, openSealed, debug, ease };
}
